INSERT INTO grammar.grammar_topics(slug,title,level,order_index,summary,guidance,learning_goals,rules,tips,source,source_metadata)
SELECT j->>'slug',j->>'title',j->>'level',(j->>'order')::integer,j->>'summary',j->>'guidance',ARRAY(SELECT jsonb_array_elements_text(j->'learningGoals')),j->'rules',ARRAY(SELECT jsonb_array_elements_text(j->'tips')),'seed','{"version":"foundations-2026-09-v2","authorship":"Grammacho; generated offline with AI assistance","kind":"original-guidance-aligned","reviewStatus":"automated-checked; educator-review-pending","referenceIds":["bc-past-continuous"],"assessment":"Practice only; approximate teaching labels, not validated CEFR assessment.","contentHash":"96c6d65cc82b241ec16c30e21e2355867131e9c8c0230502f0315bae0cab7edb","sources":[{"id":"bc-past-continuous","title":"Past continuous and past simple","publisher":"British Council","url":"https://learnenglish.britishcouncil.org/free-resources/grammar/a1-a2/past-continuous-past-simple","use":"Guidance reference only; original contexts and exercises, no publisher question text reproduced","accessed":"2026-09-13"}]}'::jsonb FROM (SELECT '{"slug":"past-continuous","title":"Past continuous and past simple","level":"A2","order":15,"summary":"Describe an activity in progress when another past event happened.","learningGoals":["A past activity in progress","Negatives and questions","A background and an event"],"guidance":"Read the rules and examples, then try a 20-question session. Explain why your chosen form fits the context and revisit any missed skill.","rules":[{"title":"A past activity in progress","explanation":"Use was or were plus an -ing form for a background activity already happening at a past moment. I, he, she and it take was; you, we and they take were.","examples":["I was sketching the view.","They were preparing breakfast."]},{"title":"Negatives and questions","explanation":"Put not after was or were. Move was or were before the subject to ask a question. Keep the -ing form.","examples":["We were not skating.","Was the dog barking?"]},{"title":"A background and an event","explanation":"The past continuous can show an activity that began before a past-simple event. The event happens during that activity; the sentence need not tell us when the activity ended.","examples":["I was sketching when the rain began.","The rain began during the sketching."]}],"tips":["Check both the meaning and the form before answering.","Use the explanation to understand a mistake before moving on.","A practice result is feedback, not an official language certificate."],"source":"seed","provenance":{"version":"foundations-2026-09-v2","authorship":"Grammacho; generated offline with AI assistance","kind":"original-guidance-aligned","reviewStatus":"automated-checked; educator-review-pending","referenceIds":["bc-past-continuous"],"assessment":"Practice only; approximate teaching labels, not validated CEFR assessment."}}'::jsonb j) payload
