SELECT id,topic_slug,level,prompt,choices,answer_id,hint,explanation,keywords,source,fingerprint,source_metadata FROM jsonb_to_recordset('[{"id":"7f7f4a14-1502-57a3-a20c-d403d2125d33","topic_slug":"past-continuous","level":"A2","prompt":"The activity was already in progress: I ____ bread dough when the doorbell rang. (knead)","choices":[{"id":"A","text":"were kneading"},{"id":"B","text":"was knead"},{"id":"C","text":"did kneading"},{"id":"D","text":"was kneading"}],"answer_id":"D","hint":"Use was or were plus an -ing form for a background activity already happening at a past moment. I, he, she and it take was; you, we and they take were.","explanation":"Use was plus kneading for the ongoing activity with “I”.","keywords":[],"source":"seed","fingerprint":"cf5e6bcda7111793f4f90ca8d0ac42df1b92219cabd95b285883c018a906b0ff","source_metadata":{"kind":"original-guidance-aligned","referenceIds":["bc-past-continuous"],"version":"foundations-2026-09-v2","reviewStatus":"automated-checked; educator-review-pending","contentHash":"96c6d65cc82b241ec16c30e21e2355867131e9c8c0230502f0315bae0cab7edb","skill":"background-form","contextKey":"background-1"}},{"id":"409a1379-4307-517e-a50b-222aa630c4b9","topic_slug":"past-continuous","level":"A2","prompt":"Use the past continuous to deny the activity: I ____ bread dough when the doorbell rang. (knead)","choices":[{"id":"A","text":"was not kneading"},{"id":"B","text":"were not kneading"},{"id":"C","text":"did not kneading"},{"id":"D","text":"was not knead"}],"answer_id":"A","hint":"Put not after was or were. Move was or were before the subject to ask a question. Keep the -ing form.","explanation":"Put not after was and keep kneading: I was not kneading.","keywords":[],"source":"seed","fingerprint":"72bf42b02c8f9c8e1eaaab6d131aa6597dec16179ba29f3b2a4945eb90412bf5","source_metadata":{"kind":"original-guidance-aligned","referenceIds":["bc-past-continuous"],"version":"foundations-2026-09-v2","reviewStatus":"automated-checked; educator-review-pending","contentHash":"96c6d65cc82b241ec16c30e21e2355867131e9c8c0230502f0315bae0cab7edb","skill":"negative","contextKey":"background-1"}},{"id":"e759f462-b899-5d26-aa3f-e7469068eb26","topic_slug":"past-continuous","level":"A2","prompt":"____ I kneading bread dough when the doorbell rang? Ask about the ongoing past activity.","choices":[{"id":"A","text":"Were"},{"id":"B","text":"Did"},{"id":"C","text":"Does"},{"id":"D","text":"Was"}],"answer_id":"D","hint":"Put not after was or were. Move was or were before the subject to ask a question. Keep the -ing form.","explanation":"Move was before the subject and retain kneading.","keywords":[],"source":"seed","fingerprint":"75052f96ca6c800c95af9df1fd390b80905d2560218ee77258eae518c7b664c9","source_metadata":{"kind":"original-guidance-aligned","referenceIds":["bc-past-continuous"],"version":"foundations-2026-09-v2","reviewStatus":"automated-checked; educator-review-pending","contentHash":"96c6d65cc82b241ec16c30e21e2355867131e9c8c0230502f0315bae0cab7edb","skill":"question","contextKey":"background-1"}},{"id":"5b2cde98-d4f0-5987-ad25-a84d3322cc2e","topic_slug":"past-continuous","level":"A2","prompt":"“I was kneading bread dough when the doorbell rang.” Which statement describes the timing?","choices":[{"id":"A","text":"The activity began only after the doorbell rang"},{"id":"B","text":"Both actions are plans for tomorrow"},{"id":"C","text":"The sentence gives an exact duration for both actions"},{"id":"D","text":"The activity of kneading bread dough had already begun"}],"answer_id":"D","hint":"The past continuous can show an activity that began before a past-simple event. The event happens during that activity; the sentence need not tell us when the activity ended.","explanation":"The continuous form shows that kneading bread dough was already happening when the doorbell rang. It does not give an exact duration.","keywords":[],"source":"seed","fingerprint":"b58925e110fe35b9b50f563067f88cc35d46b2eeb29212ef13b4c66c6aaddae4","sourc